"page.robotique-industrielle.lead1": {"fr": "Nous intégrons des robots industriels pour des applications de chargement et déchargement de machines, de palettisation, de contrôle, d’assemblage, de machines spéciales…", "en": "We integrate industrial robots for machine loading and unloading, palletizing, inspection, assembly and special-purpose machine applications…", "it": "Integriamo robot industriali per applicazioni di carico e scarico macchine, pallettizzazione, controllo, assemblaggio e macchine speciali…", "de": "Wir integrieren Industrieroboter für Anwendungen zum Be- und Entladen von Maschinen, Palettieren, Prüfen, Montieren und für Sondermaschinen…", "es": "Integramos robots industriales para aplicaciones de carga y descarga de máquinas, paletizado, inspección, ensamblaje y máquinas especiales…", "pt": "Integramos robôs industriais para aplicações de carga e descarga de máquinas, paletização, controlo, montagem e máquinas especiais…", "ro": "Integrăm roboți industriali pentru aplicații de încărcare și descărcare a mașinilor, paletizare, control, asamblare și mașini speciale…"},
"page.robotique-industrielle.lead2": {"fr": "Réalisation de cellules robotisées standards de chargement machines, de contrôle et de palettisation.", "en": "Design and manufacture of standard robotic cells for machine loading, inspection and palletizing.", "it": "Progettazione e realizzazione di celle robotizzate standard per il carico macchine, il controllo e la pallettizzazione.", "de": "Entwicklung und Bau standardisierter Roboterzellen für Maschinenbeladung, Prüfung und Palettierung.", "es": "Diseño y fabricación de células robotizadas estándar para carga de máquinas, inspección y paletizado.", "pt": "Conceção e realização de células robotizadas standard para carga de máquinas, controlo e paletização.", "ro": "Proiectarea și realizarea de celule robotizate standard pentru încărcarea mașinilor, control și paletizare."},
"page.robotique-industrielle.lead3": {"fr": "Réalisation de cellules sur mesure.", "en": "Design and manufacture of custom-built cells.", "it": "Progettazione e realizzazione di celle su misura.", "de": "Entwicklung und Bau maßgeschneiderter Zellen.", "es": "Diseño y fabricación de células a medida.", "pt": "Conceção e realização de células à medida.", "ro": "Proiectarea și realizarea de celule personalizate."},
"page.robotique-industrielle.card1.item1": {"fr": "Chargement et déchargement de machines (tour, centre d’usinage, rectifieuse, rouleuse...)", "en": "Machine loading and unloading (lathe, machining centre, grinder, rolling machine...)", "it": "Carico e scarico macchine (tornio, centro di lavoro, rettificatrice, rullatrice...)", "de": "Be- und Entladen von Maschinen (Drehmaschine, Bearbeitungszentrum, Schleifmaschine, Walzmaschine...)", "es": "Carga y descarga de máquinas (torno, centro de mecanizado, rectificadora, laminadora...)", "pt": "Carga e descarga de máquinas (torno, centro de maquinação, retificadora, laminadora...)", "ro": "Încărcarea și descărcarea mașinilor (strung, centru de prelucrare, rectificator, mașină de laminare...)"},
